/* @lc app=leetcode id=3699 lang=kotlin */ class Solution { fun zigZagArrays(n: Int, l: Int, r: Int): Int = 1_000_000_007L.let { M -> (r - l + 1).let { sz -> (3..n).fold(LongArray(sz) { it.toLong() } to LongArray(sz) { (sz - 1 - it).toLong() }) { (up, down), _ -> down.runningFold(0L) { a, b -> (a + b) % M }.let { pd -> up.runningFold(0L) { a, b -> (a + b) % M }.let { pu -> LongArray(sz) { v -> pd[v] } to LongArray(sz) { v -> (pu[sz] - pu[v + 1] + M) % M } } } }.let { (u, d) -> ((u.sum() + d.sum()) % M).toInt() } } } }